// A tracking charge commits its aim half a second before a fast straight shot.
const sandArcherSheet=new Image();sandArcherSheet.assetSrc='assets/desert-archer-v1.png';
function sandArcherReach(origin,angle){let point=d=>({x:origin.x+Math.cos(angle)*d,y:origin.y+Math.sin(angle)*d});if(lineClear(origin,point(520)))return 520;let low=0,high=520;for(let i=0;i<9;i++){let mid=(low+high)/2;if(lineClear(origin,point(mid)))low=mid;else high=mid;}return low;}
function beginSandArcher(e){let angle=Math.atan2(p.y-e.y,p.x-e.x),origin={x:e.x,y:e.y};e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'sunAim',bespoke:true,windup:1.6,origin,angle,reach:sandArcherReach(origin,angle),locked:false,fired:false};e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;}
function sandArcherLaneContains(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,c=Math.cos(a.angle),s=Math.sin(a.angle),along=dx*c+dy*s,side=-dx*s+dy*c;return along>=30-1e-8&&along<=Math.min(520,a.reach)+1e-8&&Math.abs(side)<=16+1e-8;}
const sandArcherAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{if(e.species!=='r4e3')return sandArcherAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='sunAim'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=480&&clear)beginSandArcher(e);else{e.state='idle';if(distance>750&&!e.aware)return;if(distance<=340&&clear)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,82*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 let a=e.attack;if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.2;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;if(!a.locked){let angle=Math.atan2(p.y-a.origin.y,p.x-a.origin.x);if(angle!==a.angle){a.angle=angle;a.reach=sandArcherReach(a.origin,angle);}e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;if(e.elapsed>=1.1)a.locked=true;}
 if(!a.fired&&e.elapsed>=1.6){a.fired=true;e.struck=true;a.reach=Math.min(a.reach,sandArcherReach(a.origin,a.angle));if(sandArcherLaneContains(a,p)&&lineClear(a.origin,p))hurt(72);playSound('arrow',e.x,e.y);}if(e.elapsed>=2.25){e.attack=null;e.state='idle';e.t=2.4;}
};
const sandArcherDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r4e3'||!sandArcherSheet.complete||!sandArcherSheet.naturalWidth||!sandArcherSheet.naturalHeight)return sandArcherDrawBase(e,size);let f=spriteFrame(e.hp<=0?'idle':e.state,e.hp<=0?0:e.anim);if(e.hp>0&&e.attack?.pattern==='sunAim')f={row:2,col:e.elapsed<.55?0:e.elapsed<1.6?1:e.elapsed<1.85?2:3};let q=project(e.x,e.y),sw=sandArcherSheet.naturalWidth/4,sh=sandArcherSheet.naturalHeight/3,w=148,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';let anchor=[.92,.86,.82][f.row]??.92;if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,sandArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(sandArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const sandArcherSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r4e3'?94:sandArcherSizeBase(e);
const sandArcherGroundBase=drawGroundEffects;drawGroundEffects=()=>{sandArcherGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r4e3'):enemies)){let a=e.attack;if(e.species!=='r4e3'||e.hp<=0||a?.pattern!=='sunAim'||a.reach<30||e.elapsed>=1.76||!visibleAt(e.x,e.y))continue;let c=Math.cos(a.angle),s=Math.sin(a.angle),point=(along,side)=>project(a.origin.x+c*along-s*side,a.origin.y+s*along+c*side);ctx.save();ctx.strokeStyle=a.fired?'#fff1b8':a.locked?'#ff896c':'#d5bf75';ctx.fillStyle=a.locked?'#ed684a30':'#dbc36b12';ctx.lineWidth=a.fired?3:a.locked?2:1;if(!a.locked)ctx.setLineDash([7,5]);ctx.beginPath();for(let [i,[along,side]]of [[30,-16],[a.reach,-16],[a.reach,16],[30,16]].entries()){let q=point(along,side);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();ctx.fill();ctx.stroke();if(a.fired){let from=point(30,0),to=point(a.reach,0);ctx.beginPath();ctx.moveTo(from.x,from.y-18);ctx.lineTo(to.x,to.y-18);ctx.stroke();}ctx.restore();}};
